</head>
<body>
<x-dc>
<helmet>
<link rel="preconnect" href="https://fonts.googleapis.com">
<style></style>
<style>
body{margin:0}
a{text-decoration:none;color:inherit}
.page{container-type:inline-size;container-name:page;background:#EDE6D6;color:#181A16;font-family:'Inter Tight',system-ui,sans-serif;font-size:17px;line-height:1.55}
.wrap{max-width:1240px;margin:0 auto;padding:0 40px;box-sizing:border-box;width:100%}
.eyebrow{font-weight:600;font-size:12px;line-height:1.2;letter-spacing:.16em;text-transform:uppercase}
.serif{font-family:'Source Serif 4',Georgia,serif;font-weight:400}
.h2{font-family:'Source Serif 4',Georgia,serif;font-weight:300;font-size:clamp(34px,5.4cqi,64px);line-height:1.06;margin:0;letter-spacing:-.01em;text-wrap:balance}
.btn{display:inline-flex;align-items:center;min-height:52px;padding:0 28px;font-weight:600;font-size:15px;letter-spacing:.04em;border-radius:2px}
.btn:hover{filter:brightness(1.1)}
.nav a{display:flex;align-items:center;min-height:44px;font-size:13px;font-weight:500;letter-spacing:.12em;text-transform:uppercase}
.nav a:hover{text-decoration:underline;text-underline-offset:6px}
.tag{position:absolute;left:12px;bottom:12px;background:rgba(10,12,8,.72);color:#fff;font-size:12px;line-height:1.3;padding:5px 9px;border-radius:2px;z-index:2}
.ph{position:relative;overflow:hidden;background:#333}
.ph-in{position:absolute;inset:0;transition:transform .7s ease}
.ph:hover .ph-in{transform:scale(1.035)}
.media{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
.rise{animation:rise .9s cubic-bezier(.2,.7,.2,1) both}
@keyframes rise{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
.drift{animation:drift 24s ease-in-out infinite alternate}
@keyframes drift{from{transform:scale(1.03) translateX(-1%)}to{transform:scale(1.09) translateX(1%)}}
.crops{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}
.gal{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:20px}
.ppl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.facts{display:flex;flex-wrap:wrap;gap:12px 48px}
.two{display:flex;flex-wrap:wrap;gap:48px 80px}
.phil{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 64px}
.sky-day{position:absolute;inset:0;background:linear-gradient(180deg,#8FAAB4 0%,#D8DCCB 62%,#EADFB8 100%)}
.sky-dusk{position:absolute;inset:0;background:linear-gradient(180deg,#2C2A3A 0%,#7E4A44 42%,#E0924A 76%,#F4C877 100%);opacity:.45}
.sun{position:absolute;width:150px;height:150px;border-radius:50%;background:radial-gradient(circle,#FFF8E0 0%,#F8D970 38%,rgba(248,217,112,0) 70%);left:60%;top:30%}
.shade{position:absolute;inset:0;background:#1B1208;opacity:.18}
.sun-title{color:#181A16}
.pin i{position:absolute;left:-10px;top:-10px;width:20px;height:20px;border-radius:50%;background:#E3B04B;border:3px solid #fff;box-sizing:border-box}
.pin b{position:absolute;left:-32px;top:-32px;width:64px;height:64px;border-radius:50%;border:2px solid #E3B04B;box-sizing:border-box;animation:ping 2.6s ease-out infinite}
@keyframes ping{0%{transform:scale(.3);opacity:.95}100%{transform:scale(1.5);opacity:0}}
.vil{position:absolute;display:flex;align-items:center;gap:8px;color:#fff;font-size:13px;font-weight:500;letter-spacing:.04em;text-shadow:0 1px 3px rgba(0,0,0,.85)}
.vil::before{content:'';width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 0 3px rgba(255,255,255,.25)}
@supports (animation-timeline: view()){
@keyframes sunpath{0%{left:6%;top:30%}45%{left:42%;top:8%}100%{left:84%;top:50%}}
@keyframes dusk{from{opacity:0}to{opacity:1}}
@keyframes dim{from{opacity:0}to{opacity:.5}}
@keyframes titlecol{from{color:#181A16}60%{color:#181A16}to{color:#F7EBD0}}
.sun{animation:sunpath linear both;animation-timeline:view();animation-range:cover 10% cover 90%}
.sky-dusk{animation:dusk linear both;animation-timeline:view();animation-range:cover 25% cover 90%}
.shade{animation:dim linear both;animation-timeline:view();animation-range:cover 25% cover 90%}
.sun-title{animation:titlecol linear both;animation-timeline:view();animation-range:cover 10% cover 90%}
}
@media (prefers-reduced-motion:reduce){.rise,.drift,.pin b,.sun,.sky-dusk,.shade,.sun-title{animation:none!important}}
@container page (max-width:900px){
.crops{grid-template-columns:repeat(2,minmax(0,1fr))}
.ppl{grid-template-columns:repeat(2,minmax(0,1fr))}
.ppl>.farmer{grid-row:auto!important}
}
@container page (max-width:720px){
.wrap{padding:0 20px}
.gal{grid-template-columns:1fr}
.gal>*{grid-column:auto!important}
.phil{grid-template-columns:1fr}
.sun{width:110px;height:110px}
}
@container page (max-width:520px){
.crops{grid-template-columns:1fr}
.ppl{grid-template-columns:1fr}
.ppl>*{grid-column:auto!important}
}
</style>
</helmet>
