  @keyframes glow-in{0%,25%{opacity:0}100%{opacity:1}}
  @keyframes shade-in{0%,30%{opacity:0}100%{opacity:.55}}
  @keyframes out-in{0%,78%{opacity:0}100%{opacity:1}}
  @keyframes cloud-a{from{transform:translateX(-8%)}to{transform:translateX(26%)}}
  @keyframes cloud-b{from{transform:translateX(6%)}to{transform:translateX(-24%)}}
  @keyframes hills-par{from{transform:translateY(0)}to{transform:translateY(-6%)}}
  @keyframes field-par{from{transform:translateY(0)}to{transform:translateY(8%)}}
  @keyframes copy-col{0%,40%{color:#0F1D12}75%,100%{color:#FFF1CF}}
  @keyframes copy-em{0%,40%{color:#7A2E10}75%,100%{color:#F2B31B}}
  @keyframes eyebrow-col{0%,40%{color:#10230f}75%,100%{color:#F7D26A}}
  .sunset .sky-dusk,.sunset .glow,.sunset .shade,.sunset .sun,.sunset .cloud,.sunset .hills,.sunset .field,.sunset .dark-out,.sunset .sun-copy .h2,.sunset .sun-copy .h2 em,.sunset .sun-copy .eyebrow{
    animation-timing-function:linear;animation-fill-mode:both;animation-timeline:--sunset;animation-range:cover 26% cover 74%}
  .sunset{view-timeline:--sunset block}
  .sunset .sun{animation-name:sun-set}
  .sunset .sky-dusk{animation-name:dusk-in}
  .sunset .glow{animation-name:glow-in}
  .sunset .shade{animation-name:shade-in}
  .sunset .dark-out{animation-name:out-in}
  .sunset .cloud.a{animation-name:cloud-a}
  .sunset .cloud.b{animation-name:cloud-b}
  .sunset .hills{animation-name:hills-par}
  .sunset .field{animation-name:field-par}
  .sunset .sun-copy .h2{animation-name:copy-col}
  .sunset .sun-copy .h2 em{animation-name:copy-em}
  .sunset .sun-copy .eyebrow{animation-name:eyebrow-col}
  .sunset .sky-dusk{opacity:0}
  .sunset .glow{opacity:0}
  .sunset .shade{opacity:0}
}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation:none!important;transition:none!important}
  .hero-bg{transform:scale(1.04)}
  /* static golden-hour poster, no pinned track */
  .sunset{height:auto!important}
  .stage{position:relative!important;height:88svh}
  .sunset .sky-dusk{opacity:.7}.sunset .glow{opacity:.8}.sunset .shade{opacity:.35}.sunset .dark-out{opacity:.8}
  .sunset .sun{transform:translateY(32svh) scale(1.2)}
  .sunset .sun-copy .h2,.sunset .sun-copy .eyebrow{color:#FFF1CF}
  .sunset .sun-copy .h2 em{color:var(--sun)}
  .rv,.rv-img{opacity:1;clip-path:none;transform:none}
}

/* ───────── Responsive ───────── */
@media (max-width:1000px){
  .about-photo{grid-column:1 / span 12;grid-row:auto;max-width:640px}
  .about-copy{grid-column:1 / -1;grid-row:auto;padding-top:0}
  .about-facts{grid-column:1 / -1;grid-row:auto;margin-left:0}
  .crop-photo,.crop.flip .crop-photo{grid-column:1 / -1;grid-row:1;margin-bottom:56px}
  .crop-text,.crop.flip .crop-text{grid-column:1 / -1;grid-row:2}
  .crop-inset,.crop.flip .crop-inset{right:-2%;left:auto;bottom:-14%}
  .crop p{max-width:44ch}
  .phil-fig{grid-column:1 / -1}
  .phil-fig .ph{aspect-ratio:4/3}
  .rules{grid-column:1 / -1}
  .ppl{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ppl .farmer{grid-row:auto;grid-column:1 / -1}
  .ppl .farmer .ph{min-height:0;aspect-ratio:4/3}
  .ppl .offset{margin-top:0}
  .gal .s7,.gal .s5{grid-column:span 6}
  .gal .s4,.gal .s3{grid-column:span 6}
  .gal .down,.gal .up{margin-top:0}
}
@media (max-width:720px){
  .wrap{padding:0 20px}
  .hero-body{padding-top:110px}
  .nav{gap:0 16px}
  .nav a{font-size:12px;letter-spacing:.1em}
  .gal{grid-template-columns:1fr;gap:40px}
  .gal figure{grid-column:auto!important}
  .sky{grid-template-columns:1fr;border-left-width:6px}
  .ppl{grid-template-columns:1fr}
  .ppl>*{grid-column:auto!important}
  .about-facts{padding:24px}
  .loc-card{padding-top:360px}
  .location{min-height:700px}
  .crop-inset{width:42%;border-width:6px}
  .sun{width:clamp(110px,34vw,160px)}
}

