.pin i{position:absolute;left:-10px;top:-10px;width:20px;height:20px;border-radius:50%;background:var(--sun);border:3px solid #fff;box-sizing:border-box}
.pin b{position:absolute;left:-32px;top:-32px;width:64px;height:64px;border-radius:50%;border:2px solid var(--sun);box-sizing:border-box;animation:ping 2.6s ease-out infinite}
.pin .eyebrow{position:absolute;left:20px;top:-9px;white-space:nowrap;background:var(--forest);color:#fff;padding:6px 10px;border-radius:2px}
.vil{position:absolute;display:flex;align-items:center;gap:8px;color:#fff;font-size:13px;font-weight:500;letter-spacing:.04em;text-shadow:0 1px 3px rgba(0,0,0,.85)}
.vil::before{content:'';width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 0 3px rgba(255,255,255,.25)}
.loc-card{position:relative;z-index:2;padding-top:420px;padding-bottom:40px}
.loc-card>div{background:rgba(14,35,22,.92);max-width:420px;padding:28px;display:flex;flex-direction:column;gap:14px;border-top:4px solid var(--sun)}
.loc-card .eyebrow{color:var(--sun-soft)}
.loc-card h2{font-family:var(--serif);font-size:34px;line-height:1.1;font-weight:300}
.loc-card p{color:#E5DEC6;font-size:16px}
.loc-card .coord{font-size:15px;color:#fff;letter-spacing:.04em}
.loc-card .btn{align-self:flex-start}

/* ───────── People ───────── */
.people{position:relative;padding:clamp(72px,8vw,120px) 0;background:var(--cream)}
.people .wrap{display:flex;flex-direction:column;gap:clamp(40px,5vw,64px)}
.people-head{display:flex;flex-direction:column;gap:20px;max-width:760px}
.people-head .eyebrow{color:var(--rust)}
.ppl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:36px 24px}
.ppl article{display:flex;flex-direction:column;gap:12px}
.ppl .eyebrow{color:var(--rust)}
.ppl h3{font-family:var(--serif);font-weight:400;font-size:28px;line-height:1.1}
.ppl p{font-size:15px;color:var(--ink-soft)}
.ppl .ph{aspect-ratio:4/3}
.ppl .farmer{grid-row:span 2}
.ppl .farmer .ph{flex:1 1 auto;aspect-ratio:auto;min-height:460px}
.ppl .farmer h3{font-size:36px}
.ppl .farmer .media{object-position:50% 32%}
.ppl .offset{margin-top:40px}
.sky{grid-column:1 / -1;display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:40px;align-items:center;background:var(--forest);color:var(--cream);padding:clamp(24px,3vw,40px);margin-top:20px;border-left:8px solid var(--sun)}
.sky .ph{aspect-ratio:4/5;max-height:620px;width:100%}
.sky .ph .media{object-position:50% 62%}
.sky-copy{display:flex;flex-direction:column;gap:14px;min-width:0}
.sky-badge{align-self:flex-start;color:var(--sun-soft);border:1px solid var(--sun-soft);padding:6px 10px}
.sky h3{font-family:var(--serif);font-weight:300;font-size:clamp(64px,10vw,150px);line-height:.9;letter-spacing:-.03em;color:var(--sun)}
.sky p{font-size:18px;color:#E5DEC6;max-width:36ch}

/* ───────── Philosophy ───────── */
.phil{position:relative;background:var(--wheat);color:var(--ink);padding:clamp(72px,8vw,120px) 0}
.phil .wrap{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:24px;align-items:start}
.phil-head{grid-column:1 / -1;display:flex;flex-direction:column;gap:20px;margin-bottom:24px}
.phil-head .eyebrow{color:#3C1E08}
.phil-head .h2{max-width:14ch}
.phil-head .h2 em{color:#fff4d6}
.phil-fig{grid-column:1 / span 5;display:flex;flex-direction:column;gap:12px}
.phil-fig .ph{aspect-ratio:4/5}
.phil-fig .media{object-position:50% 52%}
.phil-fig figcaption{font-size:14px;color:#2A1A08}
.rules{grid-column:7 / -1;display:flex;flex-direction:column;counter-reset:r}
.rule{counter-increment:r;border-top:2px solid rgba(22,20,14,.55);padding:22px 0 34px;display:grid;grid-template-columns:64px 1fr;gap:4px 16px}
.rule::before{content:'0' counter(r);font-family:var(--serif);font-weight:300;font-size:40px;line-height:1;color:#3C1E08;grid-row:span 2}
.rule h3{font-family:var(--serif);font-weight:400;font-size:clamp(26px,2.6vw,34px);line-height:1.12}
.rule p{color:#2A1F0C}

/* ───────── Contact / footer ───────── */
.contact{position:relative;overflow:hidden;background:var(--soil);color:var(--cream);padding:clamp(88px,10vw,150px) 0 40px}
.contact>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 60%;opacity:.5}
.contact-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(14,35,22,.82) 0%,rgba(20,16,10,.55) 45%,rgba(14,12,8,.94) 100%)}
.contact .wrap{position:relative;z-index:2;display:flex;flex-direction:column;gap:64px}
.contact .h2{font-size:clamp(44px,8.4vw,120px);max-width:12ch;line-height:.96}
.contact .h2 em{color:var(--sun)}
.contact-row{display:flex;flex-wrap:wrap;gap:32px 64px;border-top:1px solid rgba(242,228,191,.35);padding-top:32px}
.contact-row>div{display:flex;flex-direction:column;gap:6px;min-width:0}
.contact-row .eyebrow{color:var(--sun-soft)}
.contact-row a,.contact-row span.v{font-size:22px;min-height:44px;display:flex;align-items:center}
.contact-row a[href^=mailto]{text-decoration:underline;text-underline-offset:5px}
.contact-row a:hover{color:var(--sun-soft)}
.legal{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px 24px;font-size:14px;color:#D6CFBB}
.credits{font-size:12px;line-height:1.6;color:#B9B196;max-width:80ch}
.credits a{text-decoration:underline;text-underline-offset:3px}

/* ───────── Motion ───────── */
@keyframes drift{from{transform:scale(1.03) translateX(-1%)}to{transform:scale(1.09) translateX(1%)}}
@keyframes rise{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@keyframes ping{0%{transform:scale(.3);opacity:.95}100%{transform:scale(1.5);opacity:0}}
.rise{animation:rise .9s cubic-bezier(.2,.7,.2,1) both}

@supports (animation-timeline:view()){
  /* hero: parallax instead of drift */
  @keyframes hero-par{from{transform:translateY(0) scale(1.04)}to{transform:translateY(14%) scale(1.14)}}
  .hero-bg{animation:hero-par linear both;animation-timeline:scroll(root);animation-range:0 100svh}

  /* reveals — only a few key elements */
  @keyframes reveal{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
  @keyframes unveil{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
  .rv{animation:reveal linear both;animation-timeline:view();animation-range:entry 5% entry 55%}
  .rv-img{animation:unveil linear both;animation-timeline:view();animation-range:entry 0% entry 70%}

  /* parallax on crop photos & inset */
  @keyframes par{from{transform:translateY(40px)}to{transform:translateY(-40px)}}
  .crop-inset{animation:par linear both;animation-timeline:view();animation-range:cover}

  /* sunset sequence: tall track, pinned stage */
  .sunset{height:340svh;background:#2C7BC0}
  .stage{position:sticky;top:0}
  @keyframes sun-set{
    0%{transform:translateY(0) scale(1);filter:none}
    55%{transform:translateY(22svh) scale(1.08)}
    100%{transform:translateY(44svh) scale(1.38);filter:saturate(1.3) hue-rotate(-10deg)}
  }
  @keyframes dusk-in{0%,12%{opacity:0}100%{opacity:1}}
  @keyframes glow-in{0%,25%{opacity:0}100%{opacity:1}}
  @keyframes shade-in{0%,30%{opacity:0}100%{opacity:.55}}
  @keyframes out-in{0%,78%{opacity:0}100%{opacity:1}}
  @keyframes cloud-a{from{transform:translateX(-8%)}to{transform:translateX(26%)}}
  @keyframes cloud-b{from{transform:translateX(6%)}to{transform:translateX(-24%)}}
  @keyframes hills-par{from{transform:translateY(0)}to{transform:translateY(-6%)}}
  @keyframes field-par{from{transform:translateY(0)}to{transform:translateY(8%)}}
  @keyframes copy-col{0%,40%{color:#0F1D12}75%,100%{color:#FFF1CF}}
  @keyframes copy-em{0%,40%{color:#7A2E10}75%,100%{color:#F2B31B}}
  @keyframes eyebrow-col{0%,40%{color:#10230f}75%,100%{color:#F7D26A}}
  .sunset .sky-dusk,.sunset .glow,.sunset .shade,.sunset .sun,.sunset .cloud,.sunset .hills,.sunset .field,.sunset .dark-out,.sunset .sun-copy .h2,.sunset .sun-copy .h2 em,.sunset .sun-copy .eyebrow{
    animation-timing-function:linear;animation-fill-mode:both;animation-timeline:--sunset;animation-range:cover 26% cover 74%}
  .sunset{view-timeline:--sunset block}
  .sunset .sun{animation-name:sun-set}
  .sunset .sky-dusk{animation-name:dusk-in}
  .sunset .glow{animation-name:glow-in}
  .sunset .shade{animation-name:shade-in}
  .sunset .dark-out{animation-name:out-in}
  .sunset .cloud.a{animation-name:cloud-a}
  .sunset .cloud.b{animation-name:cloud-b}
  .sunset .hills{animation-name:hills-par}
  .sunset .field{animation-name:field-par}
  .sunset .sun-copy .h2{animation-name:copy-col}
  .sunset .sun-copy .h2 em{animation-name:copy-em}
  .sunset .sun-copy .eyebrow{animation-name:eyebrow-col}
  .sunset .sky-dusk{opacity:0}
  .sunset .glow{opacity:0}
  .sunset .shade{opacity:0}
}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation:none!important;transition:none!important}
  .hero-bg{transform:scale(1.04)}
  /* static golden-hour poster, no pinned track */
  .sunset{height:auto!important}
  .stage{position:relative!important;height:88svh}
  .sunset .sky-dusk{opacity:.7}.sunset .glow{opacity:.8}.sunset .shade{opacity:.35}.sunset .dark-out{opacity:.8}
  .sunset .sun{transform:translateY(32svh) scale(1.2)}
  .sunset .sun-copy .h2,.sunset .sun-copy .eyebrow{color:#FFF1CF}
  .sunset .sun-copy .h2 em{color:var(--sun)}
  .rv,.rv-img{opacity:1;clip-path:none;transform:none}
}

/* ───────── Responsive ───────── */
@media (max-width:1000px){
  .about-photo{grid-column:1 / span 12;grid-row:auto;max-width:640px}
  .about-copy{grid-column:1 / -1;grid-row:auto;padding-top:0}
  .about-facts{grid-column:1 / -1;grid-row:auto;margin-left:0}
  .crop-photo,.crop.flip .crop-photo{grid-column:1 / -1;grid-row:1;margin-bottom:56px}
  .crop-text,.crop.flip .crop-text{grid-column:1 / -1;grid-row:2}
  .crop-inset,.crop.flip .crop-inset{right:-2%;left:auto;bottom:-14%}
  .crop p{max-width:44ch}
  .phil-fig{grid-column:1 / -1}
  .phil-fig .ph{aspect-ratio:4/3}
  .rules{grid-column:1 / -1}
  .ppl{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ppl .farmer{grid-row:auto;grid-column:1 / -1}
  .ppl .farmer .ph{min-height:0;aspect-ratio:4/3}
  .ppl .offset{margin-top:0}
  .gal .s7,.gal .s5{grid-column:span 6}
  .gal .s4,.gal .s3{grid-column:span 6}
  .gal .down,.gal .up{margin-top:0}
}
@media (max-width:720px){
  .wrap{padding:0 20px}
  .hero-body{padding-top:110px}
  .nav{gap:0 16px}
  .nav a{font-size:12px;letter-spacing:.1em}
  .gal{grid-template-columns:1fr;gap:40px}
  .gal figure{grid-column:auto!important}
  .sky{grid-template-columns:1fr;border-left-width:6px}
  .ppl{grid-template-columns:1fr}
  .ppl>*{grid-column:auto!important}
  .about-facts{padding:24px}
  .loc-card{padding-top:360px}
  .location{min-height:700px}
  .crop-inset{width:42%;border-width:6px}
  .sun{width:clamp(110px,34vw,160px)}
}
"
}

arguments.content:
/* ───────── Tokens ───────── */
:root{
  --forest:#0E2316;
  --forest-2:#1A3D26;
  --soil:#14100A;
  --wheat:#C88A1A;
  --sun:#F2B31B;
  --sun-soft:#F7D26A;
  --cream:#F2E4BF;
  --ink:#16140E;
  --ink-soft:#3B3624;
  --rust:#8A3B1E;
  --serif:'Source Serif 4',Georgia,serif;
  --sans:'Inter Tight',system-ui,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:12px}
body{margin:0;background:var(--cream);color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.55;-webkit-font-smoothing:antialiased}
a{text-decoration:none;color:inherit}
img,video{display:block}
h1,h2,h3,p,figure{margin:0}
em{font-style:italic}
.wrap{max-width:1240px;margin:0 auto;padding:0 40px;width:100%}

/* ───────── Type ───────── */
.serif{font-family:var(--serif);font-weight:400}
.eyebrow{font-weight:600;font-size:12px;line-height:1.2;letter-spacing:.18em;text-transform:uppercase}
.h2{font-family:var(--serif);font-weight:300;font-size:clamp(36px,5.6vw,76px);line-height:1.02;letter-spacing:-.02em;text-wrap:balance}
.h2 em{font-weight:300;color:var(--rust)}
.btn{display:inline-flex;align-items:center;gap:10px;min-height:54px;padding:0 30px;font-weight:600;font-size:15px;letter-spacing:.05em;border-radius:2px;background:var(--sun);color:var(--ink);transition:background .25s,transform .25s}
.btn:hover{background:var(--sun-soft);transform:translateY(-2px)}
.btn::after{content:'→';transition:transform .25s}
.btn:hover::after{transform:translateX(4px)}

/* ───────── Media primitives ───────── */
.ph{position:relative;overflow:hidden;background:#2a2418}
.media{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.ph .media{transition:transform 1.1s cubic-bezier(.2,.7,.2,1)}
.ph:hover .media{transform:scale(1.04)}
.tag{position:absolute;left:12px;bottom:12px;z-index:2;background:rgba(10,12,8,.72);color:#fff;font-size:12px;line-height:1.3;padding:5px 9px;border-radius:2px}
.soil{background:
  radial-gradient(circle at 20% 30%,rgba(255,255,255,.07) 0 2px,transparent 3px) 0 0/22px 22px,
  linear-gradient(160deg,#6B5232,#2E2214)}
.soil.green{background:
  radial-gradient(circle at 20% 30%,rgba(255,255,255,.07) 0 2px,transparent 3px) 0 0/22px 22px,
  linear-gradient(160deg,#4C6A34,#1E2F18)}

/* Organic section edges */
.wave{display:block;width:100%;height:clamp(36px,6vw,90px);position:absolute;left:0;right:0;z-index:3;pointer-events:none}
.wave.w-top{top:-1px;transform:scaleY(-1)}
.wave.w-bottom{bottom:-1px}
.wave path{fill:currentColor}

/* ───────── Nav / Hero ───────── */
.hero{position:relative;min-height:max(100svh,760px);background:var(--forest);color:#fff;overflow:hidden;display:flex;flex-direction:column}
.hero-bg{position:absolute;inset:-4% 0 0;width:100%;height:104%;object-fit:cover;object-position:50% 58%;animation:drift 26s ease-in-out infinite alternate}
.hero-shade{position:absolute;inset:0;background:
  linear-gradient(180deg,rgba(8,16,10,.72) 0%,rgba(8,16,10,0) 30%,rgba(8,16,10,.08) 52%,rgba(8,16,10,.88) 100%),
  radial-gradient(120% 70% at 20% 100%,rgba(8,16,10,.6),transparent 60%)}
.site-head{position:relative;z-index:4;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:4px 32px;padding-top:16px;padding-bottom:8px}
.logo{font-family:var(--serif);font-size:24px;font-weight:600;min-height:44px;display:flex;align-items:center;letter-spacing:.01em}
.nav{display:flex;flex-wrap:wrap;gap:0 24px}
.nav a{display:flex;align-items:center;min-height:44px;font-size:13px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;text-shadow:0 1px 8px rgba(0,0,0,.45)}
.nav a:hover{color:var(--sun-soft);text-decoration:underline;text-underline-offset:7px;text-decoration-thickness:2px}
.hero-body{position:relative;z-index:4;margin-top:auto;padding-top:140px;padding-bottom:clamp(88px,11vw,150px);display:flex;flex-direction:column;gap:28px}
.hero .eyebrow{color:var(--sun-soft)}
.hero h1{font-family:var(--serif);font-weight:300;font-size:clamp(50px,9.4vw,140px);line-height:.95;letter-spacing:-.03em;max-width:11ch;text-shadow:0 2px 40px rgba(0,0,0,.35)}
.hero h1 em{color:var(--sun);font-weight:300}
.hero .lead{max-width:540px;font-size:19px;color:#F6EFD9}
.hero-cta{display:flex;flex-wrap:wrap;align-items:center;gap:16px 32px}
.hero-cta .eyebrow{color:#E9E2CA;line-height:1.8}
.hero .wave{color:var(--cream)}

/* ───────── About ───────── */
.about{position:relative;padding:clamp(72px,9vw,128px) 0 clamp(80px,9vw,128px);background:var(--cream)}
.about-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));column-gap:24px;row-gap:32px;align-items:start}
.about-photo{grid-column:1 / span 6;grid-row:1 / span 2;aspect-ratio:1/1;width:100%}
.about-photo .media{object-position:50% 40%}
.about-copy{grid-column:8 / -1;grid-row:1;display:flex;flex-direction:column;gap:22px;padding-top:12px}
.about-copy .eyebrow{color:var(--rust)}
.about-copy p{color:var(--ink-soft);text-wrap:pretty}
.about-copy .h2{font-size:clamp(34px,4.4vw,60px)}
.about-facts{grid-column:6 / -1;grid-row:2;align-self:end;display:flex;flex-wrap:wrap;gap:20px 48px;padding:30px 36px;background:var(--forest);color:var(--cream);position:relative;z-index:2;margin-left:-5%;border-top:4px solid var(--sun)}
.fact{display:flex;flex-direction:column}
.fact b{font-family:var(--serif);font-weight:300;font-size:clamp(38px,4.4vw,56px);line-height:1.05;color:var(--sun)}
.fact span{color:#E2D8B8}

/* ───────── Crops ───────── */
.crops-head{background:var(--forest);color:var(--cream);position:relative;padding:clamp(72px,8vw,120px) 0 clamp(88px,10vw,140px)}
.crops-head .wrap{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:16px 48px}
.crops-head .h2 em{color:var(--sun)}
.crops-head p{max-width:360px;color:#D5CBA9}
.crops-head .wave{color:#1F4D27}
.crop{--bg:var(--forest-2);--fg:var(--cream);--accent:var(--sun);position:relative;background:var(--bg);color:var(--fg);padding:clamp(56px,7vw,104px) 0}
.crop.soy{--bg:#1F4D27;--fg:#F2E8C8;--accent:#A9D15E}
.crop.wheat{--bg:#C58A1B;--fg:#1A140A;--accent:#5A2E0C}
.crop.corn{--bg:#6BA33A;--fg:#0F1A0A;--accent:#173B10}
.crop.sunf{--bg:#F2B31B;--fg:#1A1405;--accent:#7A2E10}
.crop-in{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));column-gap:24px;align-items:center}
.crop-photo{grid-column:1 / span 7;position:relative;aspect-ratio:var(--ar,4/3)}
.crop-photo .ph{position:absolute;inset:0}
.crop-text{grid-column:9 / -1;display:flex;flex-direction:column;gap:16px}
.crop.flip .crop-photo{grid-column:6 / -1;grid-row:1}
.crop.flip .crop-text{grid-column:1 / span 4;grid-row:1}
.crop-num{font-family:var(--serif);font-weight:300;font-size:clamp(80px,12vw,176px);line-height:.8;color:transparent;-webkit-text-stroke:1.5px var(--accent);letter-spacing:-.04em;margin-bottom:8px}
.crop h3{font-family:var(--serif);font-weight:300;font-size:clamp(46px,6vw,92px);line-height:.98;letter-spacing:-.03em}
.crop p{max-width:34ch;font-size:18px}
.crop .area{align-self:flex-start;font-size:14px;font-weight:500;letter-spacing:.06em;border-top:2px solid currentColor;padding-top:10px;margin-top:6px}
.crop-inset{position:absolute;right:-6%;bottom:-9%;width:38%;aspect-ratio:4/5;border:8px solid var(--bg);z-index:2;overflow:hidden;background:#2a2418}
.crop-inset .media{object-position:62% 50%}
.crop.flip .crop-inset{right:auto;left:-6%}

/* ───────── Sunset scroll sequence ───────── */
.sunset{position:relative;background:#2C7BC0;color:#181A16}
.stage{position:relative;height:100svh;min-height:560px;overflow:hidden;isolation:isolate;display:flex;flex-direction:column}
.sky-day,.sky-dusk,.shade,.sun,.cloud,.hills,.field,.glow,.dark-out{position:absolute}
.sky-day{inset:0;background:linear-gradient(180deg,#2C7BC0 0%,#6FB0DC 42%,#CFE3D8 66%,#F4DF9B 100%)}
.sky-dusk{inset:0;background:linear-gradient(180deg,#1B2148 0%,#5E2F55 30%,#C2503A 58%,#F28A38 76%,#FFC965 100%)}
.glow{left:0;right:0;top:0;height:100%;background:radial-gradient(60% 55% at 68% 56%,rgba(255,170,60,.65),rgba(255,120,40,0) 70%)}
.sun{width:clamp(150px,19vw,260px);aspect-ratio:1;border-radius:50%;left:calc(68% - clamp(75px,9.5vw,130px));top:9%;background:radial-gradient(circle,#FFFBE8 0 24%,#FFE48A 38%,rgba(255,200,80,.55) 56%,rgba(255,170,60,0) 72%);will-change:transform}
.cloud{height:14%;border-radius:50%;background:radial-gradient(closest-side,rgba(255,255,255,.75),rgba(255,255,255,0));filter:blur(6px)}
.cloud.a{width:46%;left:-6%;top:24%}
.cloud.b{width:38%;right:-4%;top:12%;height:11%}
.hills{left:-5%;right:-5%;bottom:34%;height:20%;color:#27421F;z-index:1}
.hills svg{width:100%;height:100%;display:block}
.field{left:0;right:0;bottom:0;height:46%;z-index:2;overflow:hidden}
.field img{position:absolute;left:0;bottom:0;width:100%;height:118%;object-fit:cover;object-position:50% 100%;
  -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 38%);mask-image:linear-gradient(180deg,transparent 0,#000 38%)}
.shade{inset:0;z-index:3;background:linear-gradient(180deg,rgba(40,16,10,0),rgba(40,16,10,.6));mix-blend-mode:multiply;pointer-events:none}
.dark-out{left:0;right:0;bottom:0;height:34%;z-index:4;background:linear-gradient(180deg,rgba(14,35,22,0),var(--forest));pointer-events:none}
.sun-copy{position:relative;z-index:5;margin-top:clamp(96px,16svh,170px);display:flex;flex-direction:column;gap:20px}
.sun-copy .h2{max-width:11ch}
/* static poster state (no scroll-driven animation support): golden hour */
.sky-dusk{opacity:.75}
.glow{opacity:.8}
.shade{opacity:.4}
.dark-out{opacity:.7}
.sun{transform:translateY(34svh) scale(1.15)}
.sun-copy .eyebrow{color:var(--sun-soft)}
.sun-copy .h2{color:#FFF1CF}
.sun-copy .h2 em{color:var(--sun)}
.sunset .wave{color:#F2B31B}

/* ───────── Machinery ───────── */
.machinery{position:relative;background:var(--forest);color:var(--cream);padding:clamp(72px,8vw,120px) 0}
.m-head{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:16px 48px;margin-bottom:clamp(40px,5vw,72px)}
.m-head .col{display:flex;flex-direction:column;gap:20px}
.m-head .eyebrow{color:var(--sun)}
.m-head .h2 em{color:var(--sun)}
.m-head p{max-width:360px;color:#D0C7A8}
.gal{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:56px 24px;align-items:start}
.gal figure{display:flex;flex-direction:column;gap:14px}
.gal .s7{grid-column:span 7}.gal .s5{grid-column:span 5}.gal .s4{grid-column:span 4}.gal .s3{grid-column:span 3}
.gal .down{margin-top:72px}
.gal .up{margin-top:-24px}
.gal figcaption{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px 16px;border-top:1px solid rgba(242,228,191,.22);padding-top:12px}
.gal figcaption .serif{font-size:clamp(22px,2.2vw,28px);line-height:1.15}
.gal figcaption span:last-child{color:#BFB68F;font-size:15px}
.gal .col-cap{flex-direction:column}

/* ───────── Location ───────── */
.location{position:relative;min-height:760px;background:#3D4F26;color:#fff;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end}
.location>svg{position:absolute;inset:0;width:100%;height:100%;display:block;filter:saturate(1.25) contrast(1.05)}
.loc-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(14,35,22,.6) 0%,rgba(14,35,22,.05) 38%,rgba(10,22,12,.82) 100%)}
.location>.tag{left:auto;right:12px;top:12px;bottom:auto}
.pin{position:absolute;left:50%;top:44%;width:0;height:0}
.pin i{position:absolute;left:-10px;top:-10px;width:20px;height:20px;border-radius:50%;background:var(--sun);border:3px solid #fff;box-sizing:border-box}
.pin b{position:absolute;left:-32px;top:-32px;width:64px;height:64px;border-radius:50%;border:2px solid var(--sun);box-sizing:border-box;animation:ping 2.6s ease-out infinite}
.pin .eyebrow{position:absolute;left:20px;top:-9px;white-space:nowrap;background:var(--forest);color:#fff;padding:6px 10px;border-radius:2px}
.vil{position:absolute;display:flex;align-items:center;gap:8px;color:#fff;font-size:13px;font-weight:500;letter-spacing:.04em;text-shadow:0 1px 3px rgba(0,0,0,.85)}
.vil::before{content:'';width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 0 3px rgba(255,255,255,.25)}
.loc-card{position:relative;z-index:2;padding-top:420px;padding-bottom:40px}
.loc-card>div{background:rgba(14,35,22,.92);max-width:420px;padding:28px;display:flex;flex-direction:column;gap:14px;border-top:4px solid var(--sun)}
.loc-card .eyebrow{color:var(--sun-soft)}
.loc-card h2{font-family:var(--serif);font-size:34px;line-height:1.1;font-weight:300}
.loc-card p{color:#E5DEC6;font-size:16px}
.loc-card .coord{font-size:15px;color:#fff;letter-spacing:.04em}
.loc-card .btn{align-self:flex-start}

/* ───────── People ───────── */
.people{position:relative;padding:clamp(72px,8vw,120px) 0;background:var(--cream)}
.people .wrap{display:flex;flex-direction:column;gap:clamp(40px,5vw,64px)}
.people-head{display:flex;flex-direction:column;gap:20px;max-width:760px}
.people-head .eyebrow{color:var(--rust)}
.ppl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:36px 24px}
.ppl article{display:flex;flex-direction:column;gap:12px}
.ppl .eyebrow{color:var(--rust)}
.ppl h3{font-family:var(--serif);font-weight:400;font-size:28px;line-height:1.1}
.ppl p{font-size:15px;color:var(--ink-soft)}
.ppl .ph{aspect-ratio:4/3}
.ppl .farmer{grid-row:span 2}
.ppl .farmer .ph{flex:1 1 auto;aspect-ratio:auto;min-height:460px}
.ppl .farmer h3{font-size:36px}
.ppl .farmer .media{object-position:50% 32%}
.ppl .offset{margin-top:40px}
.sky{grid-column:1 / -1;display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:40px;align-items:center;background:var(--forest);color:var(--cream);padding:clamp(24px,3vw,40px);margin-top:20px;border-left:8px solid var(--sun)}
.sky .ph{aspect-ratio:4/5;max-height:620px;width:100%}
.sky .ph .media{object-position:50% 62%}
.sky-copy{display:flex;flex-direction:column;gap:14px;min-width:0}
.sky-badge{align-self:flex-start;color:var(--sun-soft);border:1px solid var(--sun-soft);padding:6px 10px}
.sky h3{font-family:var(--serif);font-weight:300;font-size:clamp(64px,10vw,150px);line-height:.9;letter-spacing:-.03em;color:var(--sun)}
.sky p{font-size:18px;color:#E5DEC6;max-width:36ch}

/* ───────── Philosophy ───────── */
.phil{position:relative;background:var(--wheat);color:var(--ink);padding:clamp(72px,8vw,120px) 0}
.phil .wrap{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:24px;align-items:start}
.phil-head{grid-column:1 / -1;display:flex;flex-direction:column;gap:20px;margin-bottom:24px}
.phil-head .eyebrow{color:#3C1E08}
.phil-head .h2{max-width:14ch}
.phil-head .h2 em{color:#fff4d6}
.phil-fig{grid-column:1 / span 5;display:flex;flex-direction:column;gap:12px}
.phil-fig .ph{aspect-ratio:4/5}
.phil-fig .media{object-position:50% 52%}
.phil-fig figcaption{font-size:14px;color:#2A1A08}
.rules{grid-column:7 / -1;display:flex;flex-direction:column;counter-reset:r}
.rule{counter-increment:r;border-top:2px solid rgba(22,20,14,.55);padding:22px 0 34px;display:grid;grid-template-columns:64px 1fr;gap:4px 16px}
.rule::before{content:'0' counter(r);font-family:var(--serif);font-weight:300;font-size:40px;line-height:1;color:#3C1E08;grid-row:span 2}
.rule h3{font-family:var(--serif);font-weight:400;font-size:clamp(26px,2.6vw,34px);line-height:1.12}
.rule p{color:#2A1F0C}

/* ───────── Contact / footer ───────── */
.contact{position:relative;overflow:hidden;background:var(--soil);color:var(--cream);padding:clamp(88px,10vw,150px) 0 40px}
.contact>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 60%;opacity:.5}
.contact-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(14,35,22,.82) 0%,rgba(20,16,10,.55) 45%,rgba(14,12,8,.94) 100%)}
.contact .wrap{position:relative;z-index:2;display:flex;flex-direction:column;gap:64px}
.contact .h2{font-size:clamp(44px,8.4vw,120px);max-width:12ch;line-height:.96}
.contact .h2 em{color:var(--sun)}
.contact-row{display:flex;flex-wrap:wrap;gap:32px 64px;border-top:1px solid rgba(242,228,191,.35);padding-top:32px}
.contact-row>div{display:flex;flex-direction:column;gap:6px;min-width:0}
.contact-row .eyebrow{color:var(--sun-soft)}
.contact-row a,.contact-row span.v{font-size:22px;min-height:44px;display:flex;align-items:center}
.contact-row a[href^=mailto]{text-decoration:underline;text-underline-offset:5px}
.contact-row a:hover{color:var(--sun-soft)}
.legal{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px 24px;font-size:14px;color:#D6CFBB}
.credits{font-size:12px;line-height:1.6;color:#B9B196;max-width:80ch}
.credits a{text-decoration:underline;text-underline-offset:3px}

/* ───────── Motion ───────── */
@keyframes drift{from{transform:scale(1.03) translateX(-1%)}to{transform:scale(1.09) translateX(1%)}}
@keyframes rise{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@keyframes ping{0%{transform:scale(.3);opacity:.95}100%{transform:scale(1.5);opacity:0}}
.rise{animation:rise .9s cubic-bezier(.2,.7,.2,1) both}

@supports (animation-timeline:view()){
  /* hero: scroll parallax replaces the idle drift */
  @keyframes hero-par{from{transform:translateY(0) scale(1.04)}to{transform:translateY(14%) scale(1.14)}}
  .hero-bg{animation:hero-par linear both;animation-timeline:scroll(root);animation-range:0 100svh}

  /* reveals on a few key elements only */
  @keyframes reveal{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
  @keyframes unveil{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
  .rv{animation:reveal linear both;animation-timeline:view();animation-range:entry 5% entry 55%}
  .rv-img{animation:unveil linear both;animation-timeline:view();animation-range:entry 0% entry 70%}

  @keyframes par{from{transform:translateY(40px)}to{transform:translateY(-40px)}}
  .crop-inset{animation:par linear both;animation-timeline:view();animation-range:cover}

  /* sunset sequence: tall track with a pinned stage */
  .sunset{height:340svh;view-timeline:--sunset block}
  .stage{position:sticky;top:0}
  @keyframes sun-set{
    0%{transform:translateY(0) scale(1)}
    55%{transform:translateY(22svh) scale(1.08)}
    100%{transform:translateY(44svh) scale(1.38)}
  }
  @keyframes dusk-in{0%,12%{opacity:0}100%{opacity:1}}
  @keyframes glow-in{0%,25%{opacity:0}100%{opacity:1}}
  @keyframes shade-in{0%,30%{opacity:0}100%{opacity:.6}}
  @keyframes out-in{0%,78%{opacity:0}100%{opacity:1}}
  @keyframes cloud-a{from{transform:translateX(-8%)}to{transform:translateX(26%)}}
  @keyframes cloud-b{from{transform:translateX(6%)}to{transform:translateX(-24%)}}
  @keyframes hills-par{from{transform:translateY(0)}to{transform:translateY(-6%)}}
  @keyframes field-par{from{transform:translateY(0)}to{transform:translateY(8%)}}
  @keyframes copy-col{0%,35%{color:#0F1D12}70%,100%{color:#FFF1CF}}
  @keyframes copy-em{0%,35%{color:#7A2E10}70%,100%{color:#F2B31B}}
  @keyframes eyebrow-col{0%,35%{color:#10230f}70%,100%{color:#F7D26A}}
  .sunset .sky-dusk,.sunset .glow,.sunset .shade,.sunset .sun,.sunset .cloud,.sunset .hills,.sunset .field,.sunset .dark-out,.sunset .sun-copy .h2,.sunset .sun-copy .h2 em,.sunset .sun-copy .eyebrow{
    animation-timing-function:linear;animation-fill-mode:both;animation-duration:1ms;animation-timeline:--sunset;animation-range:cover 26% cover 74%}
  .sunset .sun{animation-name:sun-set}
  .sunset .sky-dusk{animation-name:dusk-in}
  .sunset .glow{animation-name:glow-in}
  .sunset .shade{animation-name:shade-in}
  .sunset .dark-out{animation-name:out-in}
  .sunset .cloud.a{animation-name:cloud-a}
  .sunset .cloud.b{animation-name:cloud-b}
  .sunset .hills{animation-name:hills-par}
  .sunset .field{animation-name:field-par}
  .sunset .sun-copy .h2{animation-name:copy-col}
  .sunset .sun-copy .h2 em{animation-name:copy-em}
  .sunset .sun-copy .eyebrow{animation-name:eyebrow-col}
}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation:none!important;transition:none!important}
  .hero-bg{transform:scale(1.04)}
  .sunset{height:auto!important}
  .stage{position:relative!important;height:88svh}
  .sunset .sky-dusk{opacity:.75}.sunset .glow{opacity:.8}.sunset .shade{opacity:.4}.sunset .dark-out{opacity:.7}
  .sunset .sun{transform:translateY(34svh) scale(1.15)}
  .sunset .sun-copy .eyebrow{color:var(--sun-soft)}
  .sunset .sun-copy .h2{color:#FFF1CF}
  .sunset .sun-copy .h2 em{color:var(--sun)}
}

/* ───────── Responsive ───────── */
@media (max-width:1000px){
  .about-photo{grid-column:1 / -1;grid-row:auto;max-width:640px}
  .about-copy{grid-column:1 / -1;grid-row:auto;padding-top:0}
  .about-facts{grid-column:1 / -1;grid-row:auto;margin-left:0}
  .crop-photo,.crop.flip .crop-photo{grid-column:1 / -1;grid-row:1;margin-bottom:64px}
  .crop-text,.crop.flip .crop-text{grid-column:1 / -1;grid-row:2}
  .crop-inset,.crop.flip .crop-inset{right:-2%;left:auto;bottom:-14%}
  .crop p{max-width:44ch}
  .phil-fig{grid-column:1 / -1}
  .phil-fig .ph{aspect-ratio:4/3}
  .rules{grid-column:1 / -1}
  .ppl{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ppl .farmer{grid-row:auto;grid-column:1 / -1}
  .ppl .farmer .ph{min-height:0;aspect-ratio:4/3}
  .ppl .offset{margin-top:0}
  .gal .s7,.gal .s5,.gal .s4,.gal .s3{grid-column:span 6}
  .gal .down,.gal .up{margin-top:0}
}
@media (max-width:720px){
  .wrap{padding:0 20px}
  .hero-body{padding-top:110px}
  .nav{gap:0 16px}
  .nav a{font-size:12px;letter-spacing:.1em}
  .gal{grid-template-columns:1fr;gap:40px}
  .gal figure{grid-column:auto!important}
  .sky{grid-template-columns:1fr;border-left-width:6px}
  .ppl{grid-template-columns:1fr}
  .ppl>*{grid-column:auto!important}
  .about-facts{padding:24px}
  .loc-card{padding-top:360px}
  .location{min-height:700px}
  .crop-inset{width:42%;border-width:6px}
  .sun{width:clamp(110px,34vw,160px);left:calc(68% - clamp(55px,17vw,80px))}
}

