import {spawn} from 'node:child_process';
import fs from 'node:fs';
const [,, url, w, h, outPrefix, ...ys] = process.argv;
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--remote-debugging-port=9333','--hide-scrollbars','--no-first-run','--user-data-dir=/tmp/chp'+w,'about:blank'],{stdio:'ignore'});
await new Promise(r=>setTimeout(r,2500));
const tabs=await (await fetch('http://127.0.0.1:9333/json')).json();
const ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
await new Promise(r=>ws.onopen=r);
let id=0;const pend={};
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pend[m.id]){pend[m.id](m.result);delete pend[m.id]}};
const send=(method,params={})=>new Promise(r=>{const i=++id;pend[i]=r;ws.send(JSON.stringify({id:i,method,params}))});
await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride',{width:+w,height:+h,deviceScaleFactor:1,mobile:+w<600});
await send('Page.navigate',{url});
await new Promise(r=>setTimeout(r,3500));
const ev=async x=>(await send('Runtime.evaluate',{expression:x,returnByValue:true})).result?.value;
console.log('docHeight',await ev('document.documentElement.scrollHeight'));
let i=0;
for(const y of ys){
  const yy = y.startsWith('#') ? await ev(`document.querySelector('${y}').getBoundingClientRect().top+scrollY`) : +y;
  await ev(`window.scrollTo({top:${yy},behavior:'instant'})`);
  await new Promise(r=>setTimeout(r,900));
  const r=await send('Page.captureScreenshot',{format:'jpeg',quality:70});
  fs.writeFileSync(`${outPrefix}${i++}.jpg`,Buffer.from(r.data,'base64'));
}
chrome.kill();process.exit(0);
